def _read_confirmed_findings(temp_dir: str) -> list[dict]:
    """CONFIRMED findings from the run's state.json.

    Returns a list of {file, line_range, description} dicts. Empty list
    if the file is absent or malformed. Called BEFORE temp dir cleanup
    in the per-run loop, mirroring _read_advisory_findings.
    """
    state_path = Path(temp_dir) / ".code-forge" / "state.json"
    if not state_path.exists():
        return []
    try:
        data = json.loads(state_path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return []
    confirmed = []
    for f in data.get("findings", []):
        if f.get("disposition") != "CONFIRMED":
            continue
        confirmed.append({
            "file": f.get("file", ""),
            "line_range": f.get("line_range") or None,
            "description": f.get("description", ""),
        })
    return confirmed


def _score_findings(
    entry: CorpusEntry, confirmed: list[dict]
) -> tuple[int, int, int]:
    """(hits, misses, fps) for one run against the entry's answer key.

    A hit requires an actual CONFIRMED finding matching an expected
    finding via finding_hit. An actual finding matching no expected
    finding counts as a false positive. Entries without an answer key
    score (0, 0, 0).
    """
    expected = entry.expected_findings
    if not expected:
        return (0, 0, 0)
    hits = sum(
        1 for e in expected
        if any(finding_hit(a, e) for a in confirmed)
    )
    fps = sum(
        1 for a in confirmed
        if not any(finding_hit(a, e) for e in expected)
    )
    return (hits, len(expected) - hits, fps)


def _pick_best_findings(
    per_run: list[tuple[int, int, int]],
) -> tuple[int, int, int]:
    """Best-run findings aggregation across a multi-run replay.

    Most hits wins; ties break toward fewest false positives; further
    ties keep the first run. Empty input is (0, 0, 0).
    """
    if not per_run:
        return (0, 0, 0)
